package fed

// Cross-language conformance: fogd's Go implementation must produce exactly
// the signatures the fogfed Ruby gem does, so the two wires never drift. The
// vectors are generated by clients/fogfed/conformance/generate.rb and
// verified there too; this proves Go agrees byte for byte.

import (
	"bytes"
	"crypto/ed25519"
	"crypto/hpke"
	"encoding/base64"
	"encoding/json"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"
)

type sigVector struct {
	Name            string `json:"name"`
	SeedB64         string `json:"seed_b64"`
	PublicKeyB64    string `json:"public_key_b64"`
	Method          string `json:"method"`
	Target          string `json:"target"`
	Timestamp       string `json:"timestamp"`
	Body            string `json:"body"`
	SigningString   string `json:"signing_string"`
	SignatureB64URL string `json:"signature_b64url"`
}

type transcriptVector struct {
	Name            string `json:"name"`
	SeedB64         string `json:"seed_b64"`
	Label           string `json:"label"`
	Nonce           string `json:"nonce"`
	DocJSON         string `json:"doc_json"`
	SignatureB64URL string `json:"signature_b64url"`
}

type impactVector struct {
	Name     string   `json:"name"`
	Subject  string   `json:"subject"`
	Scope    string   `json:"scope"`
	Sees     []string `json:"sees"`
	Hidden   []string `json:"hidden"`
	Floor    string   `json:"floor"`
	Addendum string   `json:"addendum"`
	Sentence string   `json:"sentence"`
}

type answerVector struct {
	Name             string `json:"name"`
	SeedB64          string `json:"seed_b64"`
	PublicKeyB64     string `json:"public_key_b64"`
	Target           string `json:"target"`
	Timestamp        string `json:"timestamp"`
	Status           int    `json:"status"`
	RequestInstance  string `json:"request_instance"`
	RequestSignature string `json:"request_signature"`
	Body             string `json:"body"`
	Digest           string `json:"digest"`
	SigningString    string `json:"signing_string"`
	SignatureB64URL  string `json:"signature_b64url"`
}

type sealVector struct {
	Name                string `json:"name"`
	RecipientSeedB64    string `json:"recipient_seed_b64"`
	RecipientPublicB64  string `json:"recipient_public_b64"`
	RecipientPrivateB64 string `json:"recipient_private_b64"`
	EphemeralSeedB64    string `json:"ephemeral_seed_b64"`
	Info                string `json:"info"`
	PlaintextB64        string `json:"plaintext_b64"`
	SealedB64           string `json:"sealed_b64"`
}

type bindingVector struct {
	Name             string `json:"name"`
	SeedB64          string `json:"seed_b64"`
	PublicKeyB64     string `json:"public_key_b64"`
	InstanceID       string `json:"instance_id"`
	EncryptionKeyB64 string `json:"encryption_key_b64"`
	BindingB64URL    string `json:"binding_b64url"`
}

type envelopeVector struct {
	Name                   string      `json:"name"`
	RequesterSeedB64       string      `json:"requester_seed_b64"`
	RequesterInstance      string      `json:"requester_instance"`
	ResponderSeedB64       string      `json:"responder_seed_b64"`
	ResponderInstance      string      `json:"responder_instance"`
	RequesterEncPrivateB64 string      `json:"requester_enc_private_b64"`
	ResponderEncPrivateB64 string      `json:"responder_enc_private_b64"`
	Timestamp              string      `json:"timestamp"`
	RequestSignature       string      `json:"request_signature"`
	RequestSealedB64       string      `json:"request_sealed_b64"`
	Method                 string      `json:"method"`
	Target                 string      `json:"target"`
	RequestHeaders         http.Header `json:"request_headers"`
	RequestBodyB64         string      `json:"request_body_b64"`
	AnswerSealedB64        string      `json:"answer_sealed_b64"`
	Status                 int         `json:"status"`
	AnswerHeaders          http.Header `json:"answer_headers"`
	AnswerBodyB64          string      `json:"answer_body_b64"`
}

type noncanonicalVector struct {
	PublicKeyB64    string   `json:"public_key_b64"`
	Timestamp       string   `json:"timestamp"`
	Target          string   `json:"target"`
	Body            string   `json:"body"`
	SignatureB64URL string   `json:"signature_b64url"`
	Signatures      []string `json:"signatures"`
	PublicKeys      []string `json:"public_keys"`
}

type instanceIDVector struct {
	PublicKeyB64 string `json:"public_key_b64"`
	InstanceID   string `json:"instance_id"`
}

type sealedTargetVector struct {
	Recipient string `json:"recipient"`
	Target    string `json:"target"`
}

type conformanceVectors struct {
	SealedTargets      []sealedTargetVector  `json:"sealed_targets"`
	InstanceIDs        []instanceIDVector    `json:"instance_ids"`
	Noncanonical       noncanonicalVector    `json:"noncanonical"`
	Envelopes          []envelopeVector      `json:"envelopes"`
	Seals              []sealVector          `json:"seals"`
	EncryptionBindings []bindingVector       `json:"encryption_bindings"`
	Signatures         []sigVector           `json:"signatures"`
	Answers            []answerVector        `json:"answers"`
	AnswerDigests      []answerVector        `json:"answer_digests"`
	Transcripts        []transcriptVector    `json:"transcripts"`
	Impacts            []impactVector        `json:"impacts"`
	Lens               map[string][]LensTerm `json:"lens"`
}

func identityFromSeedB64(t *testing.T, seedB64 string) *Identity {
	t.Helper()
	seed, err := base64.StdEncoding.DecodeString(seedB64)
	if err != nil || len(seed) != ed25519.SeedSize {
		t.Fatalf("bad seed %q: %v", seedB64, err)
	}
	priv := ed25519.NewKeyFromSeed(seed)
	return &Identity{InstanceID: "conformance", Public: priv.Public().(ed25519.PublicKey), private: priv}
}

func TestFogfed1Conformance(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("..", "..", "clients", "fogfed", "conformance", "vectors.json"))
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var v conformanceVectors
	if err := json.Unmarshal(data, &v); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	if len(v.Signatures) == 0 {
		t.Fatal("no signature vectors")
	}

	for _, c := range v.Signatures {
		id := identityFromSeedB64(t, c.SeedB64)
		if got := base64.StdEncoding.EncodeToString(id.Public); got != c.PublicKeyB64 {
			t.Errorf("%s: public key %s != %s", c.Name, got, c.PublicKeyB64)
		}
		if got := string(signingString(c.Method, c.Target, c.Timestamp, []byte(c.Body))); got != c.SigningString {
			t.Errorf("%s: signing string mismatch:\n got %q\nwant %q", c.Name, got, c.SigningString)
		}
		if got := id.Sign(c.Method, c.Target, c.Timestamp, []byte(c.Body)); got != c.SignatureB64URL {
			t.Errorf("%s: signature %s != %s", c.Name, got, c.SignatureB64URL)
		}
		at, _ := time.Parse(time.RFC3339, c.Timestamp)
		hdr := http.Header{}
		hdr.Set(HeaderTimestamp, c.Timestamp)
		hdr.Set(HeaderSignature, c.SignatureB64URL)
		if err := Verify(id.Public, c.Method, c.Target, hdr, []byte(c.Body), at); err != nil {
			t.Errorf("%s: Verify rejected a conformant signature: %v", c.Name, err)
		}
	}

	// Answers, bound to the request they answer: the Ruby gem and fogd must
	// sign and verify them identically, or every answer from one is refused
	// by the other.
	if len(v.Answers) == 0 {
		t.Fatal("no answer vectors — regenerate conformance/vectors.json")
	}
	for _, c := range v.Answers {
		id := identityFromSeedB64(t, c.SeedB64)
		req := Bound{Instance: c.RequestInstance, Sig: c.RequestSignature}
		material := AnswerMaterial(c.Status, req, []byte(c.Body))
		if got := string(signingString(methodAnswer, c.Target, c.Timestamp, material)); got != c.SigningString {
			t.Errorf("%s: answer signing string mismatch:\n got %q\nwant %q", c.Name, got, c.SigningString)
		}
		if got := id.Sign(methodAnswer, c.Target, c.Timestamp, material); got != c.SignatureB64URL {
			t.Errorf("%s: answer signature %s != %s", c.Name, got, c.SignatureB64URL)
		}
		at, _ := time.Parse(time.RFC3339, c.Timestamp)
		hdr := http.Header{}
		hdr.Set(HeaderTimestamp, c.Timestamp)
		hdr.Set(HeaderSignature, c.SignatureB64URL)
		if err := VerifyAnswer(id.Public, c.Target, hdr, c.Status, req, []byte(c.Body), at); err != nil {
			t.Errorf("%s: VerifyAnswer rejected a conformant answer: %v", c.Name, err)
		}
	}

	// Sealed bodies the Ruby gem made, byte for byte: Go derives the same
	// recipient and ephemeral keys from the same seeds, and its standard
	// library's HPKE opens the exact bytes to the exact plaintext.
	if len(v.Seals) == 0 || len(v.EncryptionBindings) == 0 {
		t.Fatal("no sealing vectors — regenerate conformance/vectors.json")
	}
	for _, c := range v.Seals {
		seed, _ := base64.StdEncoding.DecodeString(c.RecipientSeedB64)
		priv, err := sealKEM.DeriveKeyPair(seed)
		if err != nil {
			t.Fatal(err)
		}
		if got := base64.StdEncoding.EncodeToString(priv.PublicKey().Bytes()); got != c.RecipientPublicB64 {
			t.Errorf("%s: recipient key %s != %s", c.Name, got, c.RecipientPublicB64)
		}
		eseed, _ := base64.StdEncoding.DecodeString(c.EphemeralSeedB64)
		eph, _ := sealKEM.DeriveKeyPair(eseed)
		sealed, _ := base64.StdEncoding.DecodeString(c.SealedB64)
		if len(sealed) < 33 || sealed[0] != sealVersion || !bytes.Equal(sealed[1:33], eph.PublicKey().Bytes()) {
			t.Errorf("%s: header is not version 1 and the ephemeral key derived from its seed", c.Name)
		}
		want, _ := base64.StdEncoding.DecodeString(c.PlaintextB64)
		got, err := Open(priv, []byte(c.Info), sealed)
		if err != nil || !bytes.Equal(got, want) {
			t.Errorf("%s: Go opens Ruby's sealed body: %v", c.Name, err)
		}
		// And the framing is the one Go writes: the same record split.
		pk, _ := ParseEncKey(c.RecipientPublicB64)
		ours, _ := Seal(pk, []byte(c.Info), want)
		if len(ours) != len(sealed) {
			t.Errorf("%s: Go frames %d bytes where Ruby framed %d", c.Name, len(ours), len(sealed))
		}
	}
	// The envelope, both ways, as the Ruby gem made it: Go opens the
	// request to the same method, target, headers and body and verifies its
	// signature; opens the answer, verifies its head for that request, and
	// reads a body matching the head's digest.
	if len(v.Envelopes) == 0 {
		t.Fatal("no envelope vectors — regenerate conformance/vectors.json")
	}
	for _, c := range v.Envelopes {
		requester, responder := identityFromSeedB64(t, c.RequesterSeedB64), identityFromSeedB64(t, c.ResponderSeedB64)
		key := func(b64 string) hpke.PrivateKey {
			raw, _ := base64.StdEncoding.DecodeString(b64)
			k, err := sealKEM.NewPrivateKey(raw)
			if err != nil {
				t.Fatal(err)
			}
			return k
		}
		reqSealed, _ := base64.StdEncoding.DecodeString(c.RequestSealedB64)
		plain, err := Open(key(c.ResponderEncPrivateB64), RequestInfo("POST", SealedPath, c.RequesterInstance, c.ResponderInstance, c.Timestamp), reqSealed)
		if err != nil {
			t.Errorf("%s: Go opens Ruby's request: %v", c.Name, err)
			continue
		}
		method, target, hdr, body, err := DecodeInnerRequest(plain)
		wantBody, _ := base64.StdEncoding.DecodeString(c.RequestBodyB64)
		if err != nil || method != c.Method || target != c.Target || !bytes.Equal(body, wantBody) || len(hdr) != len(c.RequestHeaders) {
			t.Errorf("%s: inner request %s %s %v %q: %v", c.Name, method, target, hdr, body, err)
		}
		at, _ := time.Parse(time.RFC3339, c.Timestamp)
		h := http.Header{}
		h.Set(HeaderTimestamp, c.Timestamp)
		h.Set(HeaderSignature, c.RequestSignature)
		if err := Verify(requester.Public, "POST", SealedPath, h, reqSealed, at); err != nil {
			t.Errorf("%s: the request's signature: %v", c.Name, err)
		}
		ansSealed, _ := base64.StdEncoding.DecodeString(c.AnswerSealedB64)
		or, err := NewOpenReader(bytes.NewReader(ansSealed), key(c.RequesterEncPrivateB64),
			AnswerInfo("POST", SealedPath, c.RequesterInstance, c.RequestSignature, c.ResponderInstance))
		if err != nil {
			t.Errorf("%s: Go opens Ruby's answer: %v", c.Name, err)
			continue
		}
		bound := Bound{Instance: c.RequesterInstance, Sig: c.RequestSignature}
		head, err := readAnswerHeadAt(or, responder.Public, SealedPath, bound, at.Add(time.Second))
		if err != nil || head.Status != c.Status {
			t.Errorf("%s: answer head: %+v %v", c.Name, head, err)
			continue
		}
		got, err := io.ReadAll(newDigestReader(or, head.Digest, nil))
		want, _ := base64.StdEncoding.DecodeString(c.AnswerBodyB64)
		if err != nil || !bytes.Equal(got, want) {
			t.Errorf("%s: answer body %q: %v", c.Name, got, err)
		}
		or2, _ := NewOpenReader(bytes.NewReader(ansSealed), key(c.RequesterEncPrivateB64),
			AnswerInfo("POST", SealedPath, c.RequesterInstance, c.RequestSignature, c.ResponderInstance))
		if _, err := readAnswerHeadAt(or2, responder.Public, SealedPath, Bound{Instance: c.RequesterInstance, Sig: "another"}, at.Add(time.Second)); err == nil {
			t.Errorf("%s: the answer verified for another request", c.Name)
		}
	}

	// Both sides name a request's recipient in its signed target alike.
	if len(v.SealedTargets) == 0 {
		t.Fatal("no sealed-target vectors — regenerate conformance/vectors.json")
	}
	for _, c := range v.SealedTargets {
		if got := SealedTarget(c.Recipient); got != c.Target {
			t.Errorf("sealed target for %s: %s != %s", c.Recipient, got, c.Target)
		}
	}

	// Instance IDs derive from keys identically on both sides, and each is
	// refused with any other key.
	if len(v.InstanceIDs) == 0 {
		t.Fatal("no instance-id vectors — regenerate conformance/vectors.json")
	}
	for i, c := range v.InstanceIDs {
		pub, err := ParsePublicKey(c.PublicKeyB64)
		if err != nil {
			t.Fatal(err)
		}
		if got := DeriveInstanceID(pub); got != c.InstanceID {
			t.Errorf("instance id %d: %s != %s", i, got, c.InstanceID)
		}
		if err := CheckInstanceID(c.InstanceID, c.PublicKeyB64); err != nil {
			t.Errorf("instance id %d: %v", i, err)
		}
		other := v.InstanceIDs[(i+1)%len(v.InstanceIDs)].PublicKeyB64
		if err := CheckInstanceID(c.InstanceID, other); err == nil {
			t.Errorf("instance id %d checked out with another key", i)
		}
	}

	// Other spellings of a canonical signature or key: refused, as the gem
	// refuses them, and never a second entry in the replay record.
	nc := v.Noncanonical
	if len(nc.Signatures) != 15 || len(nc.PublicKeys) != 3 {
		t.Fatal("no non-canonical vectors — regenerate conformance/vectors.json")
	}
	ncPub, err := ParsePublicKey(nc.PublicKeyB64)
	if err != nil {
		t.Fatal(err)
	}
	ncAt, _ := time.Parse(time.RFC3339, nc.Timestamp)
	ncHdr := func(sig string) http.Header {
		h := http.Header{}
		h.Set(HeaderTimestamp, nc.Timestamp)
		h.Set(HeaderSignature, sig)
		return h
	}
	if err := Verify(ncPub, "POST", nc.Target, ncHdr(nc.SignatureB64URL), []byte(nc.Body), ncAt); err != nil {
		t.Fatalf("the canonical signature: %v", err)
	}
	for _, sig := range nc.Signatures {
		if err := Verify(ncPub, "POST", nc.Target, ncHdr(sig), []byte(nc.Body), ncAt); err == nil {
			t.Errorf("a non-canonical signature verified: %s", sig)
		}
		if _, ok := RequestDigest(Bound{Instance: "x", Sig: sig}); ok {
			t.Errorf("a non-canonical signature named a request: %s", sig)
		}
	}
	for _, k := range nc.PublicKeys {
		if _, err := ParsePublicKey(k); err == nil {
			t.Errorf("a non-canonical key parsed: %s", k)
		}
		if _, err := ParseEncKey(k); err == nil {
			t.Errorf("a non-canonical encryption key parsed: %s", k)
		}
	}

	for _, c := range v.EncryptionBindings {
		id := identityFromSeedB64(t, c.SeedB64)
		raw, _ := base64.StdEncoding.DecodeString(c.EncryptionKeyB64)
		if got := id.SignTranscript(encBindingLabel, c.InstanceID, raw); got != c.BindingB64URL {
			t.Errorf("%s: binding %s != %s", c.Name, got, c.BindingB64URL)
		}
		if err := VerifyEncBinding(id.Public, c.InstanceID, c.EncryptionKeyB64, c.BindingB64URL); err != nil {
			t.Errorf("%s: %v", c.Name, err)
		}
	}

	for _, c := range v.Transcripts {
		id := identityFromSeedB64(t, c.SeedB64)
		if got := id.SignTranscript(c.Label, c.Nonce, []byte(c.DocJSON)); got != c.SignatureB64URL {
			t.Errorf("%s: transcript %s != %s", c.Name, got, c.SignatureB64URL)
		}
		if !VerifyTranscript(id.Public, c.Label, c.Nonce, []byte(c.DocJSON), c.SignatureB64URL) {
			t.Errorf("%s: transcript does not verify", c.Name)
		}
	}

	for _, c := range v.Impacts {
		got := ImpactSentence(c.Subject, c.Scope, c.Sees, c.Hidden, c.Floor, c.Addendum)
		if got != c.Sentence {
			t.Errorf("%s: impact sentence mismatch:\n got %q\nwant %q", c.Name, got, c.Sentence)
		}
	}

	// The shared lens vocabulary must match term for term, in order — Go's
	// tables against the vectors the Ruby gem generated. A drift on either side
	// (a renamed value, a reordered axis, a stray label) fails here.
	if len(v.Lens) == 0 {
		t.Fatal("no lens vectors — regenerate conformance/vectors.json")
	}
	for axis, want := range v.Lens {
		got, ok := lensAxes[axis]
		if !ok {
			t.Errorf("lens axis %q is in the vectors but not in Go", axis)
			continue
		}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("lens axis %q mismatch:\n got %+v\nwant %+v", axis, got, want)
		}
	}
	if len(lensAxes) != len(v.Lens) {
		t.Errorf("Go has %d lens axes, vectors have %d — one side added an axis", len(lensAxes), len(v.Lens))
	}
}
